<template><div><el-timeline v-if="nodes.length"><el-timeline-item v-for="node in nodes" :key="node.todo_id" :timestamp="node.created_at" :type="node.status==='COMPLETED'?'success':node.sla_status==='OVERDUE'?'danger':'primary'"><strong>{{ node.title }}</strong><p>{{ node.todo_no }} · {{ node.status }} · 负责人 {{ node.owner_id || '候选池' }}</p></el-timeline-item></el-timeline><el-empty v-else description="暂无链路节点"/></div></template><script>export default{name:'TodoChainTimeline',props:{nodes:{type:Array,default:()=>[]}}}</script>
